const lockAlertRule = `-- name: LockAlertRule :one
SELECT id FROM alert_rules
WHERE id = $1
FOR NO KEY UPDATE
`

// Locks a rule for the transaction that records its evaluation, so two runs
// cannot step its state at once. Returns pgx.ErrNoRows when the rule was
// deleted.
func (q *Queries) LockAlertRule(ctx context.Context, id uuid.UUID) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, lockAlertRule, id)
	var id_2 uuid.UUID
	err := row.Scan(&id_2)
	return id_2, err
}

const markAlertEventNotified = `-- name: MarkAlertEventNotified :execrows
UPDATE alert_events
SET notified_at = $1::timestamptz
WHERE id = $2 AND notified_at IS NULL
`

type MarkAlertEventNotifiedParams struct {
	NotifiedAt time.Time
	ID         uuid.UUID
}

// Records the first notification of an event; later calls change nothing.
func (q *Queries) MarkAlertEventNotified(ctx context.Context, arg MarkAlertEventNotifiedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markAlertEventNotified, arg.NotifiedAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const openAlertEvent = `-- name: OpenAlertEvent :one

INSERT INTO alert_events (id, rule_id, value, started_at)
VALUES ($1, $2, $3, $4)
RETURNING id, rule_id, state, value, started_at, ended_at, notified_at
`

type OpenAlertEventParams struct {
	ID        uuid.UUID
	RuleID    uuid.UUID
	Value     float64
	StartedAt time.Time
}

// Alert events.
// Opens a triggered event for a rule. A rule has at most one open event, so
// this fails with a unique violation (alert_events_open) while one is open.
func (q *Queries) OpenAlertEvent(ctx context.Context, arg OpenAlertEventParams) (AlertEvent, error) {
	row := q.db.QueryRow(ctx, openAlertEvent,
		arg.ID,
		arg.RuleID,
		arg.Value,
		arg.StartedAt,
	)
	var i AlertEvent
	err := row.Scan(
		&i.ID,
		&i.RuleID,
		&i.State,
		&i.Value,
		&i.StartedAt,
		&i.EndedAt,
		&i.NotifiedAt,
	)
	return i, err
}

const removeChannelFromAlertRules = `-- name: RemoveChannelFromAlertRules :execrows
UPDATE alert_rules
SET channel_ids = array_remove(channel_ids, $1::uuid),
    updated_at  = now()
WHERE project_id = $2 AND channel_ids @> ARRAY[$1::uuid]
`

type RemoveChannelFromAlertRulesParams struct {
	ChannelID uuid.UUID
	ProjectID uuid.UUID
}

// Drops a deleted channel from every rule of its project that notifies it.
// Run in the same transaction as DeleteNotificationChannel.
func (q *Queries) RemoveChannelFromAlertRules(ctx context.Context, arg RemoveChannelFromAlertRulesParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeChannelFromAlertRules, arg.ChannelID, arg.ProjectID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

